"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[130],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"what-is-a-100x-ai-engineer","metadata":{"permalink":"/blog/what-is-a-100x-ai-engineer","source":"@site/blog/2026-03-01-100x-ai-engineer.md","title":"What is a 100x AI Engineer","description":"A 100x AI Engineer is someone who can:","date":"2026-03-01T00:00:00.000Z","tags":[{"inline":true,"label":"AI","permalink":"/blog/tags/ai"},{"inline":true,"label":"engineering","permalink":"/blog/tags/engineering"}],"readingTime":0.56,"hasTruncateMarker":false,"authors":[{"name":"Khajan Pandey","title":"AI Solutions Architect","url":"https://github.com/iamkhajan","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"what-is-a-100x-ai-engineer","title":"What is a 100x AI Engineer","authors":{"name":"Khajan Pandey","title":"AI Solutions Architect","url":"https://github.com/iamkhajan"},"tags":["AI","engineering"]},"unlisted":false,"nextItem":{"title":"What is coming next","permalink":"/blog/tech-radar-q1-2026"}},"content":"A 100x AI Engineer is someone who can:\\n\\n- break a problem into clear tasks,\\n- use AI tools to execute those tasks,\\n- verify outputs quickly,\\n- and ship real outcomes with speed and quality.\\n\\n## Why this matters\\n\\nToday, speed comes from systems, not only from individual effort.\\n\\nIf one engineer can use the right AI workflow, they can do the work of many manual steps in less time.\\n\\n## Let\u2019s dive deep\\n\\nTo become a 100x AI Engineer, focus on three things:\\n\\n1. **Workflow design** \u2014 define repeatable steps.\\n2. **Tool leverage** \u2014 use tools\\n3. **Execution discipline** \u2014 test, verify, and deliver consistently.\\n\\nThe goal is simple: build better systems, move faster, and keep quality high."},{"id":"tech-radar-q1-2026","metadata":{"permalink":"/blog/tech-radar-q1-2026","source":"@site/blog/2026-02-07-tech-radar.md","title":"What is coming next","description":"As a Solution Architect, my job is to filter noise. Here is my Q1 2026 Tech Radar\u2014technologies I am actively implementing for revenue-critical systems.","date":"2026-02-07T00:00:00.000Z","tags":[{"inline":true,"label":"architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"AI","permalink":"/blog/tags/ai"},{"inline":true,"label":"strategy","permalink":"/blog/tags/strategy"}],"readingTime":0.94,"hasTruncateMarker":false,"authors":[{"name":"Khajan Pandey","title":"AI Solutions Architect","url":"https://github.com/iamkhajan","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"tech-radar-q1-2026","title":"What is coming next","authors":{"name":"Khajan Pandey","title":"AI Solutions Architect","url":"https://github.com/iamkhajan"},"tags":["architecture","AI","strategy"]},"unlisted":false,"prevItem":{"title":"What is a 100x AI Engineer","permalink":"/blog/what-is-a-100x-ai-engineer"}},"content":"As a Solution Architect, my job is to filter noise. Here is my Q1 2026 Tech Radar\u2014technologies I am actively implementing for revenue-critical systems.\\n\\nLet\'s first look into the 4 pillars of the Radar:\\n\\n- **Hold**\\n- **Assess**\\n- **Trial**\\n- **Adopt**\\n\\n<div align=\\"left\\">\\n    <img src={require(\\"@site/static/img/blog_images/tech.jpeg\\").default} alt=\\"Tech Radar\\" style={{maxWidth: \'400px\', borderRadius: \'12px\'}} />\\n</div>\\n\\nFor simplification i will refer Assess and Trial to Eval\\n\\n### \ud83d\udfe2 Adopt: Multi-Agent Orchestration\\nStandard RAG is becoming a commodity. If you have not explored just try NotebookLM .The real value is now in **Agentic Workflows** where LLMs have tool-use capabilities to self-correct data retrieval. I wont be surprised if there is compnay out there building just \\"tools\\"\\n\\n### \ud83d\udfe1 Eval: Small Language Models (SLMs)\\nModels like Phi-4 or Llama-3-Tiny are proving that \\"smaller is faster\\" for specific task-oriented logic. If you are trying to solve just one domain use case , do you really need a ferrari ? \\n\\n### \ud83d\udd34 Hold: Traditional Chatbots\\nIf your AI strategy is just a wrapper around a prompt, you are building technical debt. The shift is toward **context-aware ecosystems.**"}]}}')}}]);